# Auto generated by LangBot Plugin SDK.
# StickerHub - serverless sticker / image host for human and AI replies.
# Please refer to https://langbot.app/docs/en/plugin/dev/tutor.html for more details.
from __future__ import annotations

import asyncio
import base64
import logging
import os
import stat
from pathlib import Path
from typing import Any

import httpx

from langbot_plugin.api.definition.plugin import BasePlugin

from stickerlib import (
    DEFAULT_MAX_STICKERS,
    UPLOAD_CHUNK_BYTES,
    StickerStore,
    build_media_url,
    filename_for,
    media_path,
    parse_data_url,
)

logger = logging.getLogger(__name__)

# Manifest identity. The asset URL embeds author/plugin_name, so these must stay
# in step with ``manifest.yaml``; the test suite asserts both.
AUTHOR = "langbot-team"
PLUGIN_NAME = "StickerHub"

# Process-cache slot used when no installation binding is available (dedicated
# placement). Mirrors HumanTakeover so a dedicated install keeps its own keys.
DEDICATED_SCOPE = "dedicated"
RUNTIME_PROFILE_ENV = "LANGBOT_PLUGIN_RUNTIME_PROFILE"

# Plugin asset directory that the LangBot asset route serves publicly.
ASSET_DIR = Path("assets") / "stickers"
HTTP_TIMEOUT_SECONDS = 30.0


def installation_scope(binding) -> str:
    """Return the stable scope token for one installation binding."""

    return f"{binding.instance_uuid}:{binding.workspace_uuid}:{binding.installation_uuid}"


def _ensure_writable_dir(path: Path) -> None:
    """Create ``path`` if absent and make sure the owner may write into it.

    An installed artifact tree is chmod'd to ``0o555``/``0o444`` by the SDK
    (``artifact._make_tree_read_only``), so ``mkdir``/``open`` fail with
    ``EACCES`` even for the owner and every upload silently fell back to
    plugin storage - which made every stable URL a 404. ``os.chmod`` still
    works on an owner-owned read-only directory, so re-grant the write bit and
    keep the rest of the mode as the installer left it.
    """

    path.mkdir(parents=True, exist_ok=True)
    mode = stat.S_IMODE(path.stat().st_mode)
    if mode & stat.S_IWUSR:
        return
    try:
        path.chmod(mode | stat.S_IWUSR | stat.S_IXUSR)
    except OSError:
        # Some deployments mount the artifact tree read-only at the mount
        # level (not just the permission bits). The write then still succeeds
        # when the directory is writable for another reason; if it is not, the
        # caller's OSError handler reports it.
        return


class StickerHub(BasePlugin):
    """Serverless sticker / image host.

    Stores images in this plugin's ``plugin_storage`` (content-addressed), and
    returns stable URLs pointing at the LangBot asset route. Every operation is
    installation-scoped, so several Workspaces can share one shared-runtime
    object graph without seeing each other's stickers.
    """

    def __init__(self) -> None:
        super().__init__()
        self._locks: dict[str, asyncio.Lock] = {}
        self._stores: dict[str, StickerStore] = {}
        self._warned_asset_dir = False

    # ==================== identity / lifecycle ====================

    @property
    def metadata_author(self) -> str:
        return AUTHOR

    @property
    def metadata_name(self) -> str:
        return PLUGIN_NAME

    async def initialize(self) -> None:
        """Nothing to do on the process-wide pass.

        Under shared placement this runs once per worker with an empty config and
        no installation context, so stores are created lazily per scope.
        """

        return None

    async def on_installation_revoked(self, binding) -> None:
        """Drop the revoked installation's process-local caches."""

        scope = installation_scope(binding)
        self._stores.pop(scope, None)
        self._locks.pop(scope, None)

    async def destroy(self) -> None:
        self._stores.clear()
        self._locks.clear()

    # ==================== scope / config ====================

    def _current_scope(self) -> str:
        binding = self.get_installation_binding()
        if binding is not None:
            return installation_scope(binding)
        if os.environ.get(RUNTIME_PROFILE_ENV) == "shared":
            raise RuntimeError(
                "shared invocation has no trusted installation binding; "
                "refusing to read or write tenant state"
            )
        return DEDICATED_SCOPE

    def _config(self) -> dict[str, Any]:
        return dict(self.get_config() or {})

    def _max_bytes(self) -> int:
        return max(1, int(float(self._config().get("max_sticker_mb", 8)) * 1024 * 1024))

    def _max_stickers(self) -> int:
        return max(1, int(self._config().get("max_stickers", DEFAULT_MAX_STICKERS)))

    def _public_base_url(self) -> str:
        return str(self._config().get("public_base_url") or "").strip()

    def _materialize_to_assets(self) -> bool:
        return bool(self._config().get("materialize_to_assets", True))

    def _store_for(self, scope: str) -> StickerStore:
        lock = self._locks.get(scope)
        if lock is None:
            lock = asyncio.Lock()
            self._locks[scope] = lock
        store = self._stores.get(scope)
        if (
            store is None
            or store._max_bytes != self._max_bytes()
            or store._max_stickers != self._max_stickers()
        ):
            store = StickerStore(
                self,
                scope,
                max_bytes=self._max_bytes(),
                max_stickers=self._max_stickers(),
                lock=lock,
            )
            self._stores[scope] = store
        return store

    def _store(self) -> StickerStore:
        return self._store_for(self._current_scope())

    # ==================== public API ====================

    async def add_sticker(
        self,
        name: str,
        data: bytes,
        mime: str | None = None,
        *,
        source: str = "human",
    ) -> dict[str, Any]:
        """Store one image under ``name`` and materialise it for serving."""

        store = self._store()
        meta = await store.add(
            name, data, mime, source=source, base_url=self._public_base_url()
        )
        await self._materialize(meta)
        return meta

    async def add_sticker_from_base64(
        self,
        name: str,
        data_url: str,
        *,
        source: str = "human",
    ) -> dict[str, Any]:
        """Store one ``data:`` URL / base64 image under ``name``."""

        data, mime = parse_data_url(data_url)
        if not data:
            raise ValueError("data_url must be a data: URL or base64 image")
        return await self.add_sticker(name, data, mime, source=source)

    async def add_sticker_from_url(
        self,
        name: str,
        url: str,
        *,
        source: str = "human",
    ) -> dict[str, Any]:
        """Fetch ``url`` (bounded) and store it under ``name``.

        The request is streamed so a huge response can never be buffered whole
        before the size check runs, and the blocking download runs on a worker
        thread so the plugin event loop is never stalled.
        """

        target = str(url or "").strip()
        if not target:
            raise ValueError("url is required")
        if not target.startswith(("http://", "https://")):
            raise ValueError("url must be an http(s) URL")

        max_bytes = self._max_bytes()
        # trust_env=False: do not route an arbitrary user URL through the
        # ambient proxy/proxy-env of the host. The Plugin Runtime worker carries
        # no proxy variables, and an unsupported SOCKS proxy variable makes
        # httpx raise InvalidURL before the request is even attempted.
        async with httpx.AsyncClient(
            timeout=HTTP_TIMEOUT_SECONDS, follow_redirects=True, trust_env=False
        ) as client:
            async with client.stream("GET", target) as response:
                if response.status_code >= 400:
                    raise ValueError(f"image URL returned status {response.status_code}")
                content_length = response.headers.get("content-length")
                if content_length:
                    try:
                        declared = int(content_length)
                    except ValueError:
                        declared = None
                    if declared is not None and declared > max_bytes:
                        raise ValueError(
                            f"image URL is larger than {max_bytes} bytes"
                        )
                body = bytearray()
                mime_hint = response.headers.get("content-type", "")
                try:
                    async for chunk in response.aiter_bytes(chunk_size=64 * 1024):
                        body.extend(chunk)
                        if len(body) > max_bytes:
                            raise ValueError(
                                f"image URL exceeds the {max_bytes}-byte sticker limit"
                            )
                except httpx.HTTPError as exc:
                    raise ValueError(f"image URL download failed: {exc}") from exc
        data = bytes(body)
        return await self.add_sticker(name, data, mime_hint, source=source)

    async def get_sticker(self, name: str) -> dict[str, Any] | None:
        return await self._store().get(name, base_url=self._public_base_url())

    # ==================== chunked upload ====================

    async def begin_upload(self) -> dict[str, Any]:
        """Open an upload session for the page's 256 KiB upload slices."""

        session = await self._store().begin_upload()
        return {"session": session, "chunk_bytes": UPLOAD_CHUNK_BYTES}

    async def put_upload_chunk(
        self, session: str, index: int, data: str
    ) -> dict[str, Any]:
        """Append one base64 chunk to ``session``."""

        import base64 as _base64

        try:
            payload = _base64.b64decode(str(data or ""), validate=False)
        except ValueError as exc:
            raise ValueError(f"chunk is not valid base64: {exc}") from exc
        received = await self._store().put_upload_chunk(session, index, payload)
        return {"received": received, "session": session}

    async def finish_upload(
        self, name: str, session: str, mime: str | None = None
    ) -> dict[str, Any]:
        """Assemble the session and store the sticker."""

        return await self._store().finish_upload(
            name,
            session,
            mime=mime,
            source="human",
            base_url=self._public_base_url(),
        )

    async def abort_upload(self, session: str) -> None:
        await self._store().abort_upload(session)

    async def get_sticker_bytes(self, name: str) -> tuple[bytes, dict[str, Any]] | None:
        return await self._store().get_bytes(name)

    async def list_stickers(self, *, limit: int = 100, offset: int = 0) -> dict[str, Any]:
        return await self._store().list(
            limit=limit, offset=offset, base_url=self._public_base_url()
        )

    async def count_stickers(self) -> int:
        return await self._store().total()

    async def delete_sticker(self, name: str) -> bool:
        return await self._store().delete(name)

    async def clear_stickers(self) -> int:
        return await self._store().clear()

    async def stats(self) -> dict[str, Any]:
        return await self._store().stats()

    async def media_url(self, name: str) -> str | None:
        """Return the stable absolute URL for a stored sticker, or ``None``."""

        meta = await self.get_sticker(name)
        if meta is None:
            return None
        return meta.get("url") or build_media_url(
            public_base_url=self._public_base_url(),
            author=AUTHOR,
            plugin_name=PLUGIN_NAME,
            filename=meta["filename"],
        )

    async def sticker_image(self, name: str) -> dict[str, Any] | None:
        """Return base64 image bytes for the management page preview."""

        result = await self.get_sticker_bytes(name)
        if result is None:
            return None
        data, meta = result
        return {
            "name": meta.get("slug", ""),
            "mime": meta.get("mime", "image/png"),
            "size": len(data),
            "base64": base64.b64encode(data).decode("ascii"),
            "url": await self.media_url(name),
        }

    # ==================== asset materialisation ====================

    async def _materialize(self, meta: dict[str, Any]) -> bool:
        """Best-effort copy of a blob into the plugin ``assets`` directory.

        The LangBot asset route (``/api/v1/plugins/<author>/<name>/assets/...``)
        serves files from the plugin working directory, so materialising here
        is what makes ``media_url`` fetchable on a normal (development or
        local-directory) install. Installed shared-runtime artifacts mount their
        code directory read-only; such deployments can leave the bytes in
        ``plugin_storage`` and use ``sticker_image`` through the Page, or point
        ``public_base_url`` at a reverse proxy that serves the storage.

        The write is delegated to a worker thread and never blocks the event
        loop, and failure is recorded once instead of spamming logs.
        """

        if not self._materialize_to_assets():
            return False
        filename = meta.get("filename") or filename_for(
            meta.get("slug", ""), meta.get("sha256", ""), meta.get("ext", ".png")
        )
        data = await self._store().get_bytes(meta.get("slug", ""))
        if data is None:
            return False
        payload, _ = data

        def write() -> bool:
            root = (Path.cwd() / ASSET_DIR).resolve()
            dest = (root / filename).resolve()
            if dest.parent != root:
                # Never write outside the plugin stickers directory.
                return False
            _ensure_writable_dir(root.parent)
            _ensure_writable_dir(root)
            tmp = dest.with_name(dest.name + ".tmp")
            with open(tmp, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, dest)
            return True

        try:
            return await asyncio.to_thread(write)
        except OSError as exc:
            if not self._warned_asset_dir:
                logger.warning(
                    "StickerHub could not write to %s; media_url will not be "
                    "fetchable on this deployment (%s)",
                    ASSET_DIR,
                    exc,
                )
                self._warned_asset_dir = True
            return False

    def served_path(self, filename: str) -> str:
        """Return the plugin-relative asset path served by LangBot."""

        return media_path(filename)
